import{_ as r,o as a,c as i,a2 as e}from"./chunks/framework.y1bVONfd.js";const g=JSON.parse('{"title":"开箱指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user/index.md","filePath":"zh-CN/user/index.md"}'),l={name:"zh-CN/user/index.md"};function o(n,t,s,d,h,c){return a(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="开箱指南" tabindex="-1">开箱指南 <a class="header-anchor" href="#开箱指南" aria-label="Permalink to &quot;开箱指南&quot;">​</a></h1><p>欢迎使用 CardputerZero！本指南帮助你快速上手。</p><h2 id="包装内容" tabindex="-1">包装内容 <a class="header-anchor" href="#包装内容" aria-label="Permalink to &quot;包装内容&quot;">​</a></h2><ul><li>CardputerZero 设备</li><li>USB-C 充电线</li><li>MicroSD 卡（完整版：32GB 预装系统）</li><li>快速入门卡</li></ul><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><ol><li><strong>插入 MicroSD 卡</strong>（如果未预装）</li><li><strong>按下侧面电源键</strong></li><li>等待约 30 秒系统启动</li><li><strong>APPLauncher</strong> 主界面出现</li></ol><h2 id="连接-wifi" tabindex="-1">连接 WiFi <a class="header-anchor" href="#连接-wifi" aria-label="Permalink to &quot;连接 WiFi&quot;">​</a></h2><ol><li>在主界面向右滑动到 <strong>Settings</strong></li><li>选择 <strong>WiFi</strong> → <strong>Scan</strong></li><li>从列表中选择你的网络</li><li>用键盘输入密码</li><li>完成！</li></ol><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>功能</th></tr></thead><tbody><tr><td>← →</td><td>主界面切换应用</td></tr><tr><td>OK / Enter</td><td>启动选中的应用</td></tr><tr><td>ESC</td><td>返回 / 回到主界面</td></tr><tr><td>Fn + 按键</td><td>功能快捷键</td></tr><tr><td>Ctrl+Alt+S</td><td>截屏</td></tr></tbody></table><h2 id="你能做什么" tabindex="-1">你能做什么？ <a class="header-anchor" href="#你能做什么" aria-label="Permalink to &quot;你能做什么？&quot;">​</a></h2><ul><li>🎮 <strong>玩游戏</strong> — 俄罗斯方块、乒乓、2048、小行星等</li><li>💻 <strong>终端</strong> — 完整 Bash、Python、SSH</li><li>📡 <strong>网络工具</strong> — WiFi 扫描、IP 面板、SSH 客户端</li><li>🎵 <strong>音乐</strong> — 播放音频文件</li><li>📷 <strong>拍照</strong> — 使用摄像头（完整版）</li><li>🔧 <strong>硬件</strong> — GPIO 控制、LoRa、Mesh 组网</li><li>📦 <strong>安装应用</strong> — 从 AppStore 浏览安装</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/zh-CN/user/appstore.html">从 AppStore 安装应用</a></li><li><a href="/docs/zh-CN/user/keyboard.html">键盘快捷键</a></li><li><a href="/docs/zh-CN/user/peripherals.html">连接外设</a></li><li><a href="/docs/zh-CN/user/settings.html">自定义设置</a></li></ul>',14)])])}const p=r(l,[["render",o]]);export{g as __pageData,p as default};
